function fingerprintArt(bytes){const pool=' .o+=*BOX@%&#/^SE',cols=17,rows=9,field=Array.from({length:rows},()=>Array(cols).fill(0));let x=8,y=4;for(const raw of bytes){let value=raw;for(let b=0;b<4;b++){x=Math.max(0,Math.min(cols-1,x+((value&1)?1:-1)));y=Math.max(0,Math.min(rows-1,y+((value&2)?1:-1)));if(field[y][x]<pool.length-3)field[y][x]++;value>>=2;}}field[4][8]=pool.length-2;field[y][x]=pool.length-1;return'╔═════════════════╗\n'+field.map(r=>'║'+r.map(n=>pool[n]).join('')+'║').join('\n')+'\n╚═════════════════╝';}
function showFingerprint(){const digest=(state.security.version?'9241AD570BE8D16F0487623AB41196253D75CAFE1A945807B80356297CEE42A0':'4B17862390AB10CD11528CDA36F491A7008D2F64EA19BC53D6732096AF4281E5').match(/../g);showDialog('本机身份指纹','<p>在另一台电脑上核对这台电脑的指纹。图案与完整哈希来自同一份示例指纹。</p><div class="a-tabs"><button id="ac-fp-art" aria-pressed="true">图案</button><button id="ac-fp-hash" aria-pressed="false">完整 SHA-256</button></div><pre class="a-fingerprint" id="ac-fingerprint-display"></pre>');const render=hash=>{q('#ac-fingerprint-display').textContent=hash?Array.from({length:4},(_,i)=>digest.slice(i*8,i*8+8).join(':')).join('\n'):fingerprintArt(digest.map(b=>parseInt(b,16)));q('#ac-fp-art').setAttribute('aria-pressed',String(!hash));q('#ac-fp-hash').setAttribute('aria-pressed',String(hash));};q('#ac-fp-art').onclick=()=>render(false);q('#ac-fp-hash').onclick=()=>render(true);render(false);fitDialog();}
